\begin{ex}%[6H4N2]
\immini[thm]{
Nêu tên đỉnh, cạnh, đường chéo, hai cạnh đối của hình thoi  ${MNPQ}$
}{
\begin{tikzpicture}
    % Các đỉnh của hình thoi
    \coordinate [label=left:{$M$}] (G) at (0, 0);
    \coordinate [label=above:{$N$}] (H) at (2, 3);
    \coordinate [label=right:{$P$}] (I) at (4, 0);
    \coordinate [label=below:{$Q$}] (K) at (2, -3);

    % Vẽ các cạnh của hình thoi
    \draw[thick] (G) -- (H) -- (I) -- (K) -- cycle;

    % Vẽ các đường chéo
    \draw[thick] (H) -- (K);
    \draw[thick] (G) -- (I);

    % Vẽ các điểm
    \fill (G) circle (2pt);
    \fill (H) circle (2pt);
    \fill (I) circle (2pt);
    \fill (K) circle (2pt);
\end{tikzpicture}
}
\loigiai{
Đỉnh ${M,N,P,Q}$\\
Cạnh ${MN}$, ${NP}$, ${PQ}$, ${MQ}$\\
Đường chéo ${MP}$, ${NQ}$\\
Hai cạnh đối là ${MN}$, ${PQ}$ và ${PN}$, ${MQ}$
}\end{ex}

